INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-book-t-mm-01-004-0', 't-mm-01-004', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-01-004" hidden></div>
<h2 class="mm-heading mm-h2 mm-header-banner" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[721]" style="background-color: #2F5496; color: #FFFFFF; padding: 6px 12px; border-radius: 4px; font-weight: 700; margin-top: 8pt; margin-bottom: 4pt"><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>4. SURGICAL TREATMENT OF FIBROID:</strong></span></h2>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[722]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>1. hysteroscopic myomectomy: </strong></em></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[723]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Sub mucosal intra </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>cavity fibroids. causing HMB, Subfertility</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>or miscarriage</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[724]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>S</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ub</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> mucous fibroids cause</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[725]" style="margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> HMB 6-34% </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[726]" style="margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>subfertility 2-7%,</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[727]" style="margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1-5% asymptomatic.</span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[728]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ES</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>G</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>E</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> class</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ification is useful for predicting</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> success of </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>hysteroscopic myomectomy.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[729]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Grade O &amp; I =&gt; easily</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> resec</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>table</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[730]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Gr</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ade 2 =&gt; difficulty, more complic</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ation</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>s,</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>need</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> experts.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[731]" style="margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>thickness between myoma and uterine wall up to </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>serosa</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> is an important feature to determine safety.</span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[732]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Resecto</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>scop</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ic</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> slicing i</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>s gold standard for Intra Cavity grade 0.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[733]" style="margin-left: 18pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>        </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Grade 1 &amp; 2 no prover technique.</span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[734]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Myolysis and </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Cryomyolysis</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> =&gt; </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>more </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>adhesions</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[735]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>2. open/ Lap</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>a</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>roscopic Myomectomy:</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[736]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>techniques to reduce intraoperative</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> bl</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>oo</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>d loss.</span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[737]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>GnRH Analogues</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[738]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>SPRM</span></span></div>
