INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-book-t-mm-01-006-0', 't-mm-01-006', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-01-006" hidden></div>
<h2 class="mm-heading mm-h2 mm-header-banner" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[833]" style="background-color: #2F5496; color: #FFFFFF; padding: 6px 12px; border-radius: 4px; font-weight: 700; margin-top: 8pt; margin-bottom: 4pt"><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>6</strong></span><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>. </strong></span><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>MENOPAUSE AND </strong></span><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>MANAGEMENT</strong></span><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>:</strong></span><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><em><strong> </strong></em></span></h2>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[834]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><em><strong>Average age 50.5years 1 year earlier in smokers</strong></em></u></span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[835]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><em><strong>Perimenopause:</strong></em></u></span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[836]" style="margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Interval leading to menopause, an</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ovulatory cycle</span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[837]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><em><strong>Climacteric:</strong></em></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> period between Reproductive to non-reproductive life.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[838]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>              </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>It includes Menopause.</span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[839]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><em><strong>POF:</strong></em></u></span><span class="mm-run" style=''color: #FF0000; font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''color: #FF0000; font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>&lt; 40years</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[840]" style="margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> turner syndrome, Fragile X, Autoimmune Disorders, idiopathic.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[841]" style="margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1% of women experience POF</span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[842]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><em><strong>Early menopause</strong></em></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> &lt; 45</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> years </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>between age of 40 – 45 yrs.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[843]" style="margin-left: 36pt"><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>E and P =&gt;    </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>FSH </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Pulsatility</span></p>
<figure class="mm-figure" data-mm-figure-id="60f5d7794838444a297b870d" data-mm-topic-id="t-mm-01-006"><svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Source figure 60f5d7794838444a297b870d" viewbox="1171575 -9525 228600 304800" preserveaspectratio="xMidYMid meet" data-mm-object-manifest="e3c4bc7daeb50fba28a2d03bf7d287243cf51e7b8c8b32185ef93ff5d8455e71"><defs><marker id="arrow-end-db990cfebc8d3afa8c96" markerwidth="10" markerheight="7" refx="9" refy="3.5" orient="auto" markerunits="strokeWidth"><path d="M 0 0 L 10 3.5 L 0 7 Z" fill="#000000"></path></marker></defs><g data-mm-object-id="db990cfebc8d3afa8c96" transform="translate(1292317 35075)"><g transform="translate(0 0)"><path d="M 0 0 L 1 153281" fill="none" fill-opacity="0" stroke="#000000" stroke-opacity="1" stroke-width="12700" marker-end="url(#arrow-end-db990cfebc8d3afa8c96)"></path></g></g></svg></figure>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[844]" style="margin-left: 36pt"><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>E and P =&gt; </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Menopausal symptoms more in 1</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>st</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> year.</span></p>
<figure class="mm-figure" data-mm-figure-id="15b7fa8c28c2d3e7cfad1607" data-mm-topic-id="t-mm-01-006"><svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Source figure 15b7fa8c28c2d3e7cfad1607" viewbox="1181100 -28575 238125 304800" preserveaspectratio="xMidYMid meet" data-mm-object-manifest="dca5c575c2eae64254feafefa9eebfb88e74d84dca4e8179d06637e08493eb88"><defs><marker id="arrow-end-7fa2c8129a7f699f621b" markerwidth="10" markerheight="7" refx="9" refy="3.5" orient="auto" markerunits="strokeWidth"><path d="M 0 0 L 10 3.5 L 0 7 Z" fill="#000000"></path></marker></defs><g data-mm-object-id="7fa2c8129a7f699f621b" transform="translate(1309106 18995)"><g transform="translate(0 0)"><path d="M 0 0 L 1 153281" fill="none" fill-opacity="0" stroke="#000000" stroke-opacity="1" stroke-width="12700" marker-end="url(#arrow-end-7fa2c8129a7f699f621b)"></path></g></g></svg></figure>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[845]" style="margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>After 1-year</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> estrogen </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>production</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> starts</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> from non-ovarian</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> source leading to reduced symptoms.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[846]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>    </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Menopause: </strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[847]" style="margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>When women </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>have</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> no periods for one ear or more between 45 – 55 years.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[848]" style="text-align: center; margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Diagnosis:</strong></u></span></p>
<figure class="mm-figure" data-mm-figure-id="ad0f2a9a0f0d24d3cddb3cad" data-mm-topic-id="t-mm-01-006"><svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Source figure ad0f2a9a0f0d24d3cddb3cad" viewbox="2562225 161925 57150 266700" preserveaspectratio="xMidYMid meet" data-mm-object-manifest="18473f5f8e61dfec7d4a8e207c985791aa9cc11ee5b7166e25c768dd2cdc03e7"><g data-mm-object-id="6c4c9232002a15f4858a" transform="translate(2571420 171780)"><g transform="translate(0 0)"><path d="M 0 0 L 1 211422" fill="none" fill-opacity="0" stroke="#4472C4" stroke-opacity="1" stroke-width="12700"></path></g></g></svg></figure>
<figure class="mm-figure" data-mm-figure-id="86aa875a1658a9d1060c4095" data-mm-topic-id="t-mm-01-006"><svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Source figure 86aa875a1658a9d1060c4095" viewbox="1266825 0 2343150 447675" preserveaspectratio="xMidYMid meet" data-mm-object-manifest="e403d118ec1e0d573ef0437e6bb9986aca0e9b39412bdba47db7f5c1207949b7"><defs><marker id="arrow-end-8d51827ca6610e5ca44e" markerwidth="10" markerheight="7" refx="9" refy="3.5" orient="auto" markerunits="strokeWidth"><path d="M 0 0 L 10 3.5 L 0 7 Z" fill="#4472C4"></path></marker><marker id="arrow-end-3577e436f4edf384b272" markerwidth="10" markerheight="7" refx="9" refy="3.5" orient="auto" markerunits="strokeWidth"><path d="M 0 0 L 10 3.5 L 0 7 Z" fill="#4472C4"></path></marker></defs><g data-mm-object-id="260973171d67a347e75f" transform="translate(1392742 43925)"><g transform="translate(0 0) translate(1046539 10270) rotate(0) scale(1 -1) translate(-1046539 -10270)"><path d="M 0 0 L 2093078 20540" fill="none" fill-opacity="0" stroke="#4472C4" stroke-opacity="1" stroke-width="12700"></path></g></g><g data-mm-object-id="8d51827ca6610e5ca44e" transform="translate(1389380 56917)"><g transform="translate(0 0) translate(3732 143691.5) rotate(0) scale(-1 1) translate(-3732 -143691.5)"><path d="M 0 0 L 7464 287383" fill="none" fill-opacity="0" stroke="#4472C4" stroke-opacity="1" stroke-width="12700" marker-end="url(#arrow-end-8d51827ca6610e5ca44e)"></path></g></g><g data-mm-object-id="3577e436f4edf384b272" transform="translate(3487756 48830)"><g transform="translate(0 0) translate(3732 143691.5) rotate(0) scale(-1 1) translate(-3732 -143691.5)"><path d="M 0 0 L 7464 287383" fill="none" fill-opacity="0" stroke="#4472C4" stroke-opacity="1" stroke-width="12700" marker-end="url(#arrow-end-3577e436f4edf384b272)"></path></g></g></svg></figure>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[850]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>&gt; 45 (No labs)</strong></em></span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>        </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>&gt;</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong> 40 – </strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>45</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong> </strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[851]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Clinical diagnosis based on:</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>   </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>&gt; </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>45yrs</span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[852]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">1.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Amenorrhea</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 1 year</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>   F</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>SH &gt; 30IU</span></span></div>
