INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-book-t-mm-01-006-1', 't-mm-01-006', 'document_html', '<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[923]" style="padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>HRT</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[924]" style="padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Raloxifene SERM</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[925]" style="padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Tibolone with GnRH</span><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''> analogue</span><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''> if given for &gt; 6months.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[926]" style="padding-left: 54pt"><span class="mm-list-marker" aria-hidden="true">2.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Therapeutic</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[927]" style="padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Bisphosphate + Calcium 1.5g + vitamin D 400 - 600 daily.</span></span></div>
