INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-book-t-mm-01-008-0', 't-mm-01-008', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-01-008" hidden></div>
<h2 class="mm-heading mm-h2 mm-header-banner" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1019]" style="background-color: #2F5496; color: #FFFFFF; padding: 6px 12px; border-radius: 4px; font-weight: 700; margin-top: 8pt; margin-bottom: 4pt"><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>8</strong></span><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>. HRT AFTER GYNAECOLOGICAL MALIGNANCY:</strong></span></h2>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1020]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Ovarian Cancer:</strong></u></span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1021]" style="margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>(Avoid)</span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1022]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Endometrial Cancer:</strong></u></span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1023]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>Type 1: Stage 1 and 2 </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1024]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>      </span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''> E only if no chance of</span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''> malignant</span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''> foc</span><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>us</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1025]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>Type 1: Stage 3 and 4 avoid.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1026]"><span class="mm-run" style=''font-family: "Aptos", sans-serif; font-size: 12pt''>Type 2: Avoid.</span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1027]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>C</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>ervical</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong> Cancer</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>: </strong></u></span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1028]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>squ</span><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>amous</span><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''> cell ca</span><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>rcinoma</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1029]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>stage 1 and 2</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1030]" style="margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>C</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ontinuous combined therapy (CCT) or</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> Estrogen </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>(a</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ccording</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> to </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>status of </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>uterus)</span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1031]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>stage 3 &amp; 4 – Avoid.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1032]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Adenocarcinoma (avoid)</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1033]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Vaginal + vulval Cancer: </strong></u></span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1034]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Seq cell = Estrogen or CCT.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1035]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>non seq – avoid</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1036]" style="margin-bottom: 8pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1037]" style="margin-bottom: 8pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1038]" style="margin-bottom: 8pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[1039]" style="margin-bottom: 8pt"> </p>', 0);

