INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-book-t-mm-02-002-0', 't-mm-02-002', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-02-002" hidden></div>
<div class="mm-heading mm-h3 mm-header-banner mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2286]" style="background-color: #9CC2E5; color: #FFFFFF; padding: 6px 12px; border-radius: 4px; font-weight: 700; margin-top: 8pt; margin-bottom: 4pt; padding-left: 54pt"><span class="mm-list-marker" aria-hidden="true">1.</span><span class="mm-list-body"><span class="mm-run" style=''color: #FFFFFF; font-family: "Aptos", sans-serif; font-size: 14pt''><u><strong>ASSESSMENT OF MALE PARTNER:</strong></u></span><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''><u><strong> </strong></u></span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2287]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">1.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Semen Analysis</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>:</strong></u></span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2288]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>WHO criteria:</strong></em></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2289]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">1.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>PH = 7.2</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> or more.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2290]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">2.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Volume = 1.5ml or more.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2291]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">3.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Sperm count = 39million/ ejaculate or more.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2292]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">4.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Sperm con</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>c</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>e</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ntration</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> = 15million/ml or more.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2293]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">5.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Motility:</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2294]" style="margin-bottom: 8pt; padding-left: 108pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Total 40%.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2295]" style="margin-bottom: 8pt; padding-left: 108pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Progressive 32%.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2296]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">6.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Vitality = 58% or more.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2297]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">7.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Morphology = 4% normal or more.</span></span></div>
<figure class="mm-figure" data-mm-figure-id="ace8855de40a3b8489fbccd1" data-mm-topic-id="t-mm-02-002"><svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Source figure ace8855de40a3b8489fbccd1" viewbox="2324100 200025 257175 514350" preserveaspectratio="xMidYMid meet" data-mm-object-manifest="f105a7a6406c4855475620f1efab82fc81daea95788ff5667d1d86659cbbdec3"><defs><marker id="arrow-end-26efbcc7c96a1705323f" markerwidth="10" markerheight="7" refx="9" refy="3.5" orient="auto" markerunits="strokeWidth"><path d="M 0 0 L 10 3.5 L 0 7 Z" fill="#4472C4"></path></marker></defs><g data-mm-object-id="26efbcc7c96a1705323f" transform="translate(2453005 250825)"><g transform="translate(0 0)"><path d="M 0 0 L 1 358775" fill="none" fill-opacity="0" stroke="#4472C4" stroke-opacity="1" stroke-width="12700" marker-end="url(#arrow-end-26efbcc7c96a1705323f)"></path></g></g></svg></figure>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2298]" style="margin-bottom: 8pt; margin-left: 72pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2299]" style="text-align: center; margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Repeat Testing:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2300]" style="text-align: center"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>3months</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> routinely if abnormality </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>detected</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2301]" style="text-align: center"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Except Azoospermia</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> or severe ol</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>i</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>g</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ospermia</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<figure class="mm-figure" data-mm-figure-id="5e3b3a048cf5af7f246267cf" data-mm-topic-id="t-mm-02-002"><svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Source figure 5e3b3a048cf5af7f246267cf" viewbox="2076450 -123825 228600 447675" preserveaspectratio="xMidYMid meet" data-mm-object-manifest="6ce364d5fb170bdda60f1d02b120afd140a62668a6632f96dc1a44d6f58018c5"><defs><marker id="arrow-end-8c93606c2eb1aab4c5fc" markerwidth="10" markerheight="7" refx="9" refy="3.5" orient="auto" markerunits="strokeWidth"><path d="M 0 0 L 10 3.5 L 0 7 Z" fill="#4472C4"></path></marker></defs><g data-mm-object-id="8c93606c2eb1aab4c5fc" transform="translate(2200910 -71917)"><g transform="translate(0 0)"><path d="M 0 0 L 1 277495" fill="none" fill-opacity="0" stroke="#4472C4" stroke-opacity="1" stroke-width="12700" marker-end="url(#arrow-end-8c93606c2eb1aab4c5fc)"></path></g></g></svg></figure>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2303]" style="text-align: center; margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Repeat as early as possible.</span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2304]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">2.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Anti-Sperm Anti bodies: N</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>ot recommended</strong></span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2305]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">3.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>PCT = N</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>ot recommended</strong></span></span></div>', 0);

