INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-book-t-mm-02-010-0', 't-mm-02-010', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-02-010" hidden></div>
<h2 class="mm-heading mm-h2 mm-header-banner" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2749]" style="background-color: #2F5496; color: #FFFFFF; padding: 6px 12px; border-radius: 4px; font-weight: 700; margin-top: 8pt; margin-bottom: 4pt"><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>4. ASSESSMENT OF INFERTILE MALE</strong></span></h2>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2750]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>1/7 couple experience infertility – 50% male – 37% in Ivf treated infertility.</strong></u></span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[2751]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>30% male factor, combination of </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>male and female </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>= 40%.</strong></u></span></span></div>
