INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-book-t-mm-03-007-1', 't-mm-03-007', 'document_html', '<figure class="mm-figure" data-mm-figure-id="f3a51aa4d7e36b7bed7ca10f" data-mm-topic-id="t-mm-03-007"><svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Source figure f3a51aa4d7e36b7bed7ca10f" viewbox="857250 -9525 190500 219075" preserveaspectratio="xMidYMid meet" data-mm-object-manifest="499b9c83ed967404b3c81dedd703268b188fe84b3b23d80856b04cd017b67a3c"><g data-mm-object-id="03770071c65812b9be61" transform="translate(889000 5080)"><g transform="translate(0 0)"><path d="M 0 88900 L 28575 88900 L 28575 0 L 85725 0 L 85725 88900 L 114300 88900 L 57150 146050 Z" fill="#FFFFFF" fill-opacity="1" stroke="#4472C4" stroke-opacity="1" stroke-width="12700"></path></g></g></svg></figure>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4399]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 9pt''><u><strong>      </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 9pt''><u><strong> </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 9pt''><u><strong>Restaging </strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4400]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''><u><strong>Recurrence</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''><u><strong> </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''><u><strong>:</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 10pt''><u><strong>8 – 73%.</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4401]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Relapse:</strong></u></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4402]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>with invasive implants – 21% over 5 years.</strong></u></span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4403]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>with non – invasive implants 2%.</strong></u></span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4404]" style="margin-left: 18pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>DNA aneuploidy </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>19-fold</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>     in invasive implants.</strong></u></span></p>
<figure class="mm-figure" data-mm-figure-id="c2b3d666387431002f0d6c12" data-mm-topic-id="t-mm-03-007"><svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Source figure c2b3d666387431002f0d6c12" viewbox="2124075 -85725 247650 314325" preserveaspectratio="xMidYMid meet" data-mm-object-manifest="dedf769a9f6b467bbf3cfc08f9e1bdc0b91528635a356a544e18ef4139e8719a"><defs><marker id="arrow-end-4611e5b79b4f923a2941" markerwidth="10" markerheight="7" refx="9" refy="3.5" orient="auto" markerunits="strokeWidth"><path d="M 0 0 L 10 3.5 L 0 7 Z" fill="#000000"></path></marker></defs><g data-mm-object-id="4611e5b79b4f923a2941" transform="translate(2249326 5837)"><g transform="translate(0 0) translate(2445 75792.5) rotate(0) scale(1 -1) translate(-2445 -75792.5)"><path d="M 0 0 L 4890 151585" fill="none" fill-opacity="0" stroke="#000000" stroke-opacity="1" stroke-width="12700" marker-end="url(#arrow-end-4611e5b79b4f923a2941)"></path></g></g></svg></figure>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4405]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>12 – 58% after cystectomy.</strong></u></span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4406]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>0 – 20% after USO/BSO.</strong></u></span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4407]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>2.5 – 5.7% after completion surgery.</strong></u></span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4408]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Restaging</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong> depends upon</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>:</strong></u></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4409]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Aneuploidy status – DNA.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4410]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Micro papillary status.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4411]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Invasive implants.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4412]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>No fertility concerns.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4413]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Fertility in BOT:</strong></u></span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4414]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Conservative Treatment.</span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4415]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>S</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>pontaneous conception: 32 – 65%.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4416]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>OI: 13 – 29%.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4417]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>OI only in stage 1 disease for limited cycles.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4418]" style="margin-left: 18pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>OI = ovulati</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>on</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4419]" style="margin-left: 18pt"> </p>
