INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-book-t-mm-03-009-0', 't-mm-03-009', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-03-009" hidden></div>
<div class="mm-heading mm-h2 mm-header-banner mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4540]" style="background-color: #2F5496; color: #FFFFFF; padding: 6px 12px; border-radius: 4px; font-weight: 700; margin-top: 8pt; margin-bottom: 4pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">9.</span><span class="mm-list-body"><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>OVARIAN CANCER</strong></span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4541]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>S/S =&gt; IBS symptoms over 12m</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>0</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4542]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Persistent abd</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ominal</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> pain/pelvic pain</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4543]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Feeling full/loss of appetite.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[4544]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Abd disten</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>tion bloating.</span></span></div>
