INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-book-t-mm-05-016-1', 't-mm-05-016', 'document_html', '<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[7475]" style="margin-bottom: 10pt"><span class="mm-run" style=''color: #44546A; font-family: "Calibri", sans-serif; font-size: 9pt''><em>Table </em></span><span class="mm-run" style=''color: #44546A; font-family: "Calibri", sans-serif; font-size: 9pt''><em>24</em></span><span class="mm-run" style=''color: #44546A; font-family: "Calibri", sans-serif; font-size: 9pt''><em>. </em></span><span class="mm-run" style=''color: #44546A; font-family: "Calibri", sans-serif; font-size: 9pt''><em>Summary of intrauterine contraceptives in current UK clinical practice</em></span></p>
