INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-book-t-mm-06-002-0', 't-mm-06-002', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-06-002" hidden></div>
<h2 class="mm-heading mm-h2 mm-header-banner" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8010]" style="background-color: #2F5496; color: #FFFFFF; padding: 6px 12px; border-radius: 4px; font-weight: 700; margin-top: 8pt; margin-bottom: 4pt"><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>2. </strong></span><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>CAESAREAN SECTION:</strong></span></h2>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8011]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Informed decision about child birth – so offer </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>evidence-based</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> information.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8012]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Info during AN period to all women </span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8013]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Risk of C/S 1 – in 4.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8014]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Info includes:</strong></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8015]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Indications</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8016]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Procedure involved</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8017]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Risks/ Benefits.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8018]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Implications for future pregnancies</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8019]" style="margin-bottom: 8pt; margin-left: 18pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>&amp; birth after C/S.</span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8020]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Discuss Risk/ Benefits of C/S &amp; NVD.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8021]" style="margin-bottom: 8pt; margin-left: 18pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>C/S:</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8022]" style="margin-bottom: 8pt; margin-left: 18pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Risk of:</strong></em></span></p>
<figure class="mm-figure" data-mm-figure-id="e5b7cc3821eff829a44047da" data-mm-topic-id="t-mm-06-002"><svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Source figure e5b7cc3821eff829a44047da" viewbox="504825 -19050 228600 295275" preserveaspectratio="xMidYMid meet" data-mm-object-manifest="446ce10695bb10ecde0a39d1b125e9034607ed9a7d139609d17b3c8b3d93f2c3"><defs><marker id="arrow-end-a04f6fb92b484dbed2bf" markerwidth="10" markerheight="7" refx="9" refy="3.5" orient="auto" markerunits="strokeWidth"><path d="M 0 0 L 10 3.5 L 0 7 Z" fill="#000000"></path></marker></defs><g data-mm-object-id="a04f6fb92b484dbed2bf" transform="translate(628015 34719)"><g transform="translate(0 0)"><path d="M 0 0 L 1 132138" fill="none" fill-opacity="0" stroke="#000000" stroke-opacity="1" stroke-width="12700" marker-end="url(#arrow-end-a04f6fb92b484dbed2bf)"></path></g></g></svg></figure>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8023]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Perineal/ Abdominal Pain 3 days PP</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8024]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Injury to Vagina</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8025]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Early PPH</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8026]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Obs shock</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8027]" style="margin-bottom: 8pt; margin-left: 18pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Risk of:</strong></em></span></p>
<figure class="mm-figure" data-mm-figure-id="5d0625ea4ed007ddb9334243" data-mm-topic-id="t-mm-06-002"><svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Source figure 5d0625ea4ed007ddb9334243" viewbox="514350 -76200 228600 285750" preserveaspectratio="xMidYMid meet" data-mm-object-manifest="fff0ee7b77738d2539893c67b713d8b4ddd38b7b65c3be8b58ee9854fd8c3cc1"><defs><marker id="arrow-end-625c9bf05760a948aaaa" markerwidth="10" markerheight="7" refx="9" refy="3.5" orient="auto" markerunits="strokeWidth"><path d="M 0 0 L 10 3.5 L 0 7 Z" fill="#000000"></path></marker></defs><g data-mm-object-id="625c9bf05760a948aaaa" transform="translate(639016 10160)"><g transform="translate(0 0) translate(0 66040) rotate(0) scale(1 -1) translate(0 -66040)"><path d="M 0 0 L 1 132080" fill="none" fill-opacity="0" stroke="#000000" stroke-opacity="1" stroke-width="12700" marker-end="url(#arrow-end-625c9bf05760a948aaaa)"></path></g></g></svg></figure>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8028]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Neonatal ICU Admission</span></span></div>
<figure class="mm-figure" data-mm-figure-id="ab8c334b4182e90fcb92c3d6" data-mm-topic-id="t-mm-06-002"><svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Source figure ab8c334b4182e90fcb92c3d6" viewbox="742950 114300 228600 285750" preserveaspectratio="xMidYMid meet" data-mm-object-manifest="6d3e0631e7e62fb079a9108be4d2f0b113bac199d28dca260289829edd420158"><defs><marker id="arrow-end-3ab859669b92e6595a6c" markerwidth="10" markerheight="7" refx="9" refy="3.5" orient="auto" markerunits="strokeWidth"><path d="M 0 0 L 10 3.5 L 0 7 Z" fill="#000000"></path></marker></defs><g data-mm-object-id="3ab859669b92e6595a6c" transform="translate(866981 201930)"><g transform="translate(0 0) translate(0 66040) rotate(0) scale(1 -1) translate(0 -66040)"><path d="M 0 0 L 1 132080" fill="none" fill-opacity="0" stroke="#000000" stroke-opacity="1" stroke-width="12700" marker-end="url(#arrow-end-3ab859669b92e6595a6c)"></path></g></g></svg></figure>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8029]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Hospital stay</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8030]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Hysterectomy</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> due to PPH</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8031]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Cardiac arrest.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8032]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Maternal request for C/S due to anxiety – Mental health support.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8033]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>No C/S due to obesity.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8034]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Factors reducing likelihood of Caesarean Section:</strong></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8035]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">1.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Continuous support.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8036]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">2.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Partogram with 4 hours’ action line.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8037]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">3.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Consultant obs involved in decision making for C/S.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8038]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>No influence of Likelihood of Caesarean Section:</strong></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8039]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">1.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Walking in labour</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8040]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">2.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Non supine in II stage of labour.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8041]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">3.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Water birth</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8042]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">4.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Epidural analgesia</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8043]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">5.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Use of raspberry leaves.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8044]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Don’t offer early </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>amniotomy</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> a</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>nd</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> active management of labor to reduce risk.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8045]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Elective C/S after 39 weeks.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8046]" style="text-align: center; margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Classification of Caesarean Section</strong></u></span></p>
