INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-book-t-mm-06-003-0', 't-mm-06-003', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-06-003" hidden></div>
<h2 class="mm-heading mm-h2 mm-header-banner" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8212]" style="background-color: #2F5496; color: #FFFFFF; padding: 6px 12px; border-radius: 4px; font-weight: 700; margin-top: 8pt; margin-bottom: 4pt"><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>3. </strong></span><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>PREVENTING ENTRY RELATED GYAECOLOGICAL LAPROSCOPIC INJURIES:</strong></span></h2>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8213]" style="margin-left: 18pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>250,000 women/year undergo lap</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>a</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ro</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>scopy</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> in UK.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8214]" style="margin-left: 18pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Serious complications = 1/1000</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8215]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Incidence of complications:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8216]" style="margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Intestinal 0.6/1000 – 15% identified post op</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8217]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Urological 0.1/1000</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8218]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Vascular 0.1/1000</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8219]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Death 3 – 8/100,000</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8220]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>57% injuries</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> are</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> entry related.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8221]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Risk population:</strong></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8222]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Low BMI – vascular injuries</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8223]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>TAH – </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>50% of mucosal </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Bladder injuries</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> are missed I</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>/O</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8224]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Common entry </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>related injury</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>= Bowel</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> injury, commonly in</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8225]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Obese</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> or </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Underweight</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8226]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>With previous surgery</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> or </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Peritonitis</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8227]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>IBD</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8228]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Laparoscopic Positions:</strong></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8229]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Entry and removal of trocar</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> in</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> flat</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> position</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8230]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Rest procedure LLOID devis position.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8231]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Avoid</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> Trendelenburg</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8232]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Laparoscopic Entry Techniques:</strong></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8233]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">1.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Open Hasson Technique:</strong></em></span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8234]" style="margin-bottom: 8pt; padding-left: 54pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Bowel</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> injury </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>0.4/1000</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8235]" style="margin-bottom: 8pt; padding-left: 54pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Vessels</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> injury</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 0.3/1000</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8236]" style="margin-bottom: 8pt; padding-left: 54pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Use of stay </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>sutures</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8237]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Extreme BMI</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8238]" style="margin-top: 12pt; margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Prevent vascular injury.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8239]" style="margin-top: 12pt; margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">2.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Close</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong> Technique</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>:</strong></em></span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8240]" style="margin-bottom: 8pt; padding-left: 54pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Max</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 2 attempts</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8241]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Enter </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Ver</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ese nee</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>dle from base </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>of umbilicus</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8242]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Ensure d</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ouble clicks.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8243]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Must be d</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>isposable.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8244]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Vertical entery</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8245]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Must be s</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>harp</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8246]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>OT table flat</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8247]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Abdominal palpation before insertion </span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8248]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Avoid ex</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>c</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>essive lateral moments to avoid Bowel</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> injuries.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8249]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Non elevation of </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>abdomen </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>=&gt; less entry failure.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8250]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>I/Abdominal Pressure:</strong></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8251]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>20 – 25</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>mmhg</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> to safely insert P</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>0</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> Trocar</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8252]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>12 – 15</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>mmhg </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> operating pressure.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8253]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Abdominal pressure =&gt; more distance from umbilicus so less injury.</span></p>
<figure class="mm-figure" data-mm-figure-id="972b584b3a9dd4fcccb38c49" data-mm-topic-id="t-mm-06-003"><svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Source figure 972b584b3a9dd4fcccb38c49" viewbox="723900 -76200 238125 266700" preserveaspectratio="xMidYMid meet" data-mm-object-manifest="f9105d17e338d97e6ef47565111de77d9d9e5227f04a3b163a575ccc46f18742"><defs><marker id="arrow-end-89c2b2f557d6136ae619" markerwidth="10" markerheight="7" refx="9" refy="3.5" orient="auto" markerunits="strokeWidth"><path d="M 0 0 L 10 3.5 L 0 7 Z" fill="#000000"></path></marker></defs><g data-mm-object-id="89c2b2f557d6136ae619" transform="translate(850900 11430)"><g transform="translate(0 0) translate(0 60325) rotate(0) scale(1 -1) translate(0 -60325)"><path d="M 0 0 L 1 120650" fill="none" fill-opacity="0" stroke="#000000" stroke-opacity="1" stroke-width="12700" marker-end="url(#arrow-end-89c2b2f557d6136ae619)"></path></g></g></svg></figure>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8254]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>10mm Hg – create the space about 0.6cm.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8255]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>25mm Hg – 5.6cm </span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8256]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>5</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>-</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>6 lit of Co</span>­<span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sub>2</sub></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> is required to create this pressure of 25mmHg.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8257]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>P</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup><strong>0</strong></sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong> Trocar Insertion &amp; Safety Points:</strong></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8258]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Thinnest portion of umbilicus.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8259]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Vertical/ 90</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>0</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> insertion with the base of umblicus</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8260]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Introduce laparoscope</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8261]" style="margin-bottom: 8pt; margin-left: 54pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Rotate 360</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>0</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> to check </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8262]" style="margin-bottom: 8pt; margin-left: 54pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Any injury or adhesions</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8263]" style="margin-bottom: 8pt; margin-left: 54pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Observe haemorrhage, haematoma</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[8264]" style="margin-bottom: 8pt; margin-left: 54pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Injury suspected or adhesion suspected.</span></p>
<figure class="mm-figure" data-mm-figure-id="5c092b9f77bbc9c7124ef743" data-mm-topic-id="t-mm-06-003"><svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Source figure 5c092b9f77bbc9c7124ef743" viewbox="1304925 9525 323850 457200" preserveaspectratio="xMidYMid meet" data-mm-object-manifest="bb93ff1a5705c6649df0c475f51349660bc7ff44aa57367dde1bd3cc710a128c"><g data-mm-object-id="952e5a84d912dd7a87d1" transform="translate(1333500 17780)"><g transform="translate(0 0)"><path d="M 0 276225 L 61912.5 276225 L 61912.5 0 L 185737.5 0 L 185737.5 276225 L 247650 276225 L 123825 400050 Z" fill="#FFFFFF" fill-opacity="1" stroke="#4472C4" stroke-opacity="1" stroke-width="12700"></path></g></g></svg></figure>
