INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-book-t-mm-06-028-0', 't-mm-06-028', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-06-028" hidden></div>
<h2 class="mm-heading mm-h2" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9356]" style="margin-top: 8pt; margin-bottom: 4pt"><span class="mm-run" style=''color: #2F5496; font-family: "Calibri Light", sans-serif; font-size: 16pt''>17.9.</span><span class="mm-run" style=''color: #2F5496; font-family: "Calibri Light", sans-serif; font-size: 16pt''>4</span><span class="mm-run" style=''color: #2F5496; font-family: "Calibri Light", sans-serif; font-size: 16pt''>. ACUTE COLONIC PSEUDO – OBSTRUCTION (ACPO) AFTER C/S:</span></h2>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9357]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Ogilivie Syndrome:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9358]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1/500 delivery 400/year</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9359]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Parasympathetic underactivity, sympathectic over activity.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9360]" style="margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>10% due to C/Section and pelvic surgery.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9361]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Sympathetic:</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> L</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sub>2 </sub></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>–</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sub> </sub></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>L</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sub>5 </sub></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>=&gt; inferior mesentric and pelvic ganglion.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9362]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Para:</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> vagus + Hypogestic plexus S</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sub>1</sub></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> – S</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sub>4</sub></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9363]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Risk Factor:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9364]" style="margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Age</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9365]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Anticholinergic drugs</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9366]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Alpa – agonist sympathomimetics</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9367]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Cells of cajal in colon</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[9368]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Hypokelemia, hypomegnesimea</span></p>
