INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-book-t-mm-07-004-1', 't-mm-07-004', 'document_html', '<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10222]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">1.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>UPT should be performed in all cases of persistent / irregular </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>bleeding</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> after pregnancy last &gt;8weeks.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10223]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">2.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Symptoms of metastatic </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>d</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>isease,</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> dyspnea, hemoptysis, </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>seizures</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10224]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">3.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Biopsy from vagina is not recommended.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10225]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>GTD center Referral:</strong></u></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10226]" style="padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">1.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Stable incomplete evacuation.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[10227]" style="padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">2.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>  ed </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>β</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> – HCG after 2 doses of metho after PUL.</span></span></div>
