INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-book-t-mm-08-004-0', 't-mm-08-004', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-08-004" hidden></div>
<h2 class="mm-heading mm-h2 mm-header-banner" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[11419]" style="background-color: #2F5496; color: #FFFFFF; padding: 6px 12px; border-radius: 4px; font-weight: 700; margin-top: 8pt; margin-bottom: 4pt; margin-left: 36pt"><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>4. VTE IN PREGNANCY &amp; PUERPERIUM</strong></span></h2>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[11420]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>Suspected PE</strong></em></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong> (pulmonary embolism)</strong></em></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[11421]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Clinical assessment.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[11422]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Perform CXR, ECG.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[11423]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>CBC, LFT’S, RFTS.</span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[11424]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Start LMWH (unless C/I).</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[11425]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>In suspected PE =&gt; look for</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[11426]" style="margin-bottom: 8pt; margin-left: 72pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>S</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>igns and symptoms</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong> of DVT:</strong></u></span></p>
<figure class="mm-figure" data-mm-figure-id="6917d0962b8121603d36b838" data-mm-topic-id="t-mm-08-004"><svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Source figure 6917d0962b8121603d36b838" viewbox="600075 152400 3190875 571500" preserveaspectratio="xMidYMid meet" data-mm-object-manifest="2594b34034dc691409b17d8176259e445361852aa12c19ff623253220ee0e90b"><defs><marker id="arrow-end-ae8a227a03c6ea6ce3fd" markerwidth="10" markerheight="7" refx="9" refy="3.5" orient="auto" markerunits="strokeWidth"><path d="M 0 0 L 10 3.5 L 0 7 Z" fill="#4472C4"></path></marker></defs><g data-mm-object-id="7c60abc9c9fa24380c32" transform="translate(2154803 162091)"><g transform="translate(0 0)"><path d="M 0 0 L 1 151074" fill="none" fill-opacity="0" stroke="#4472C4" stroke-opacity="1" stroke-width="12700"></path></g></g><g data-mm-object-id="388198ff31ec2b9f3dbd" transform="translate(612140 303061)"><g transform="translate(0 0) translate(1528638.5 12216.5) rotate(0) scale(1 -1) translate(-1528638.5 -12216.5)"><path d="M 0 0 L 3057277 24433" fill="none" fill-opacity="0" stroke="#4472C4" stroke-opacity="1" stroke-width="12700"></path></g></g><g data-mm-object-id="ae8a227a03c6ea6ce3fd" transform="translate(3666490 297981)"><g transform="translate(0 0)"><path d="M 0 0 L 3810 325755" fill="none" fill-opacity="0" stroke="#4472C4" stroke-opacity="1" stroke-width="12700" marker-end="url(#arrow-end-ae8a227a03c6ea6ce3fd)"></path></g></g></svg></figure>
