INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-book-t-mm-08-028-1', 't-mm-08-028', 'document_html', '<div class="mm-table-scroll mm-table-floating-reflow" role="region" tabindex="0" data-mm-tblp-left-from-text="180" data-mm-tblp-right-from-text="180" data-mm-tblp-vert-anchor="text" data-mm-tblp-horz-anchor="margin" data-mm-tblp-y="371" style="clear:both;margin-left:9pt;margin-right:9pt;"><table class="mm-table" style="border-collapse:collapse;width:481.7pt;table-layout:fixed;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;"><colgroup><col style="width:77.75pt;"><col style="width:99.2pt;"><col style="width:134.65pt;"><col style="width:170.1pt;"></colgroup><tbody><tr><td style="white-space:pre-wrap;width:77.75pt;background-color:#BDD6EE;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''><strong>Feature</strong></span></p></td><td style="white-space:pre-wrap;width:99.2pt;background-color:#BDD6EE;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''><strong>HELLP</strong></span></p></td><td style="white-space:pre-wrap;width:134.65pt;background-color:#BDD6EE;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''><strong>TTP/HUS</strong></span></p></td><td style="white-space:pre-wrap;width:170.1pt;background-color:#BDD6EE;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''><strong>AFLP</strong></span></p></td></tr><tr><td style="white-space:pre-wrap;width:77.75pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>Incidence </span></p></td><td style="white-space:pre-wrap;width:99.2pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>1/100</span></p><p style="margin:0;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>10 – 30% of severe PE</span></p></td><td style="white-space:pre-wrap;width:134.65pt;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''>1/25,000</span></p></td><td style="white-space:pre-wrap;width:170.1pt;border-top:0