INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-book-t-mm-08-044-0', 't-mm-08-044', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-08-044" hidden></div>
<h3 class="mm-heading mm-h3 mm-header-banner" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[15242]" style="background-color: #9CC2E5; color: #FFFFFF; padding: 6px 12px; border-radius: 4px; font-weight: 700; margin-top: 8pt; margin-bottom: 4pt"><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>3</span><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>8</span><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>.</span><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>1.</span><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''> MANAGEMENT OF HYPOTHYROIDISM AND RELATED DISORDERS</span></h3>
<div class="mm-table-scroll" role="region" tabindex="0"><table class="mm-table" style="border-collapse:collapse;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;"><colgroup><col style="width:134.85pt;"><col style="width:134.85pt;"><col style="width:134.9pt;"><col style="width:134.9pt;"></colgroup><tbody><tr><td style="white-space:pre-wrap;width:134.85pt;background-color:#BDD6EE;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;"></p></td><td style="white-space:pre-wrap;width:134.85pt;background-color:#BDD6EE;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''><strong>OH</strong></span></p><p style="margin:0;text-align:center;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''><strong>Over</strong></span><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''><strong>t</strong></span><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''><strong> Hypothyroidism</strong></span></p></td><td style="white-space:pre-wrap;width:134.9pt;background-color:#BDD6EE;border-top:0.5pt solid #000000;border-right:0.5pt solid #000000;border-bottom:0.5pt solid #000000;border-left:0.5pt solid #000000;padding-top:0pt;padding-right:5.4pt;padding-bottom:0pt;padding-left:5.4pt;"><p style="margin:0;text-align:center;margin-bottom:8pt;"><span class="mm-run" style=''font-family:"Calibri", sans-serif;font-size:12pt''><strong>S