INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-book-t-mm-09-014-0', 't-mm-09-014', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-09-014" hidden></div>
<h3 class="mm-heading mm-h3 mm-header-banner" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16998]" style="background-color: #9CC2E5; color: #FFFFFF; padding: 6px 12px; border-radius: 4px; font-weight: 700; margin-top: 8pt; margin-bottom: 4pt"><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>1.13.</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>HEMOPHILUS INFLUENZAE</span></h3>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[16999]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>G – negative Aerobic bacilli.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17000]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Commensal of vaginal flora can cause:</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17001]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Chorioamni</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>oni</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>tis.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17002]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Endometritis.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17003]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Neonatal infection.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17004]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Diagnosis = culture / ELIZA.</span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17005]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Hemophiles</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> Ducreyi = STD, </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>chancroid</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17006]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Cause:</strong></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17007]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>PTB.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17008]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>LBW.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17009]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Treatment in Pregnancy:</strong></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17010]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Azithromycin.</span></span></div>
<figure class="mm-figure" data-mm-figure-id="d42e25ae1eb0a81f74af570e" data-mm-topic-id="t-mm-09-014"><svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Source figure d42e25ae1eb0a81f74af570e" viewbox="1981200 9525 76200 590550" preserveaspectratio="xMidYMid meet" data-mm-object-manifest="d1323adc44aae0976b81fe3ed57a78758122383ff04dc973a731808f76eea1ee"><g data-mm-object-id="d0f9b0d50ee1538a6c43" transform="translate(1990538 20225)"><g transform="translate(0 0)"><path d="M 0 0 A 45719 3809.76427 0 0 1 45719 3809.76427 L 45719 556458.23573 A 45719 3809.76427 0 0 1 0 560268 Z" fill="none" fill-opacity="0" stroke="#4472C4" stroke-opacity="1" stroke-width="12700"></path><path d="M 0 0 A 45719 3809.76427 0 0 1 45719 3809.76427 L 45719 556458.23573 A 45719 3809.76427 0 0 1 0 560268" fill="none" fill-opacity="0" stroke="#4472C4" stroke-opacity="1" stroke-width="12700"></path></g></g></svg></figure>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17011]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Erythromycin.</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Ch</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>anc</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>roid.</strong></span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17012]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Ceftriaxone.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17013]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>H – Influenza: cephalosporin.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17014]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Annual vaccination recommended by WHO.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17015]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Vaccine safe in pregnancy &amp; B.F.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17016]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>H1N1:</strong></u></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17017]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>RNA virus.</strong></u></span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17018]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Infect birds and mammals.</strong></u></span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17019]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Transmission by aerosol + direct contact.</strong></u></span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17020]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Neuraminidase is involved in release of new viruses from infected cells.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17021]" style="margin-bottom: 8pt; margin-left: 36pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17022]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>   </strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Treatment:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17023]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Oseltamivir</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>- Inhibit </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>neuraminidase</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> + halt viral </span><span class="mm-tab" aria-hidden="true">	</span></p>
<figure class="mm-figure" data-mm-figure-id="d83e2f93c0866f8659f57779" data-mm-topic-id="t-mm-09-014"><svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Source figure d83e2f93c0866f8659f57779" viewbox="1190625 0 76200 447675" preserveaspectratio="xMidYMid meet" data-mm-object-manifest="b86e16e7d30bcbb961cc11123e17a0f52d51823ac59ef6251de1c2f8574b27f8"><g data-mm-object-id="5fdcab7533c6bd8dd7b1" transform="translate(1197705 14888)"><g transform="translate(0 0)"><path d="M 0 0 A 45719 3809.76427 0 0 1 45719 3809.76427 L 45719 403177.23573 A 45719 3809.76427 0 0 1 0 406987 Z" fill="none" fill-opacity="0" stroke="#4472C4" stroke-opacity="1" stroke-width="12700"></path><path d="M 0 0 A 45719 3809.76427 0 0 1 45719 3809.76427 L 45719 403177.23573 A 45719 3809.76427 0 0 1 0 406987" fill="none" fill-opacity="0" stroke="#4472C4" stroke-opacity="1" stroke-width="12700"></path></g></g></svg></figure>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17024]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Zanamivir</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>replication.</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>- More effective if started within few </span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>hours</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> of onset of symptoms.</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>- Licensed for use within 48 hours of </span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>symptoms onset </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>and can be</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 11pt''>given</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> within 7 days.</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>- Duration of symptoms by 11.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>5</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>days.</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>-   Risk of complications</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17025]" style="margin-bottom: 8pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17026]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>PEP:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17027]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Oseltamivir within 48 hours of exposure.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17028]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Zanamivir within 36 hours of exposure.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17029]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Prevention:</strong></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17030]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Vaccination </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>pander mix</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> – yearly.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17031]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Avoidance of exposure.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17032]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Antiviral prophylaxis in case of exposure.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17033]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Severe disease =&gt; referral to hospital.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17034]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Influenza:</strong></u></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17035]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Fever, </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>myalgia</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>, SOB, cough.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17036]" style="margin-bottom: 8pt; margin-left: 18pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>O/E</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>   </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>reduced</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> air entry, coa</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>r</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>se crackles @ base.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17037]" style="margin-bottom: 8pt; margin-left: 18pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>CXR</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> one lobe is collapsed / consolidation throughout both lungs.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17038]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Atypical pneumonia</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u>:</u></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17039]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Fever, </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>myalgia</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>, SOB, cough.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17040]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Examination same as influenza</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17041]" style="margin-bottom: 8pt; margin-left: 18pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>C</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>XR:</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> lower </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>lobe</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> collapse/ consolidation throughout both </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>lungs’</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> sputum negative for </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>gram stain</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ing and culture negative.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17042]" style="margin-bottom: 8pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17043]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Streptococcus Pneumonia:</strong></u></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[17044]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Fever, SOB, cough.</span></span></div>
