INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-book-t-mm-09-022-0', 't-mm-09-022', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-09-022" hidden></div>
<div class="mm-heading mm-h2 mm-header-banner mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18539]" style="background-color: #2F5496; color: #FFFFFF; padding: 6px 12px; border-radius: 4px; font-weight: 700; margin-top: 8pt; margin-bottom: 4pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">9.</span><span class="mm-list-body"><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>MULTIPLE PREGNANCY:</strong></span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18540]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u>Timing of division and consequences</u></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18541]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Two cell stage = DADC.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18542]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Blastocytic stage = MCDA.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18543]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Bilaminar Disc = MAMC.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18544]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Twins in general 1:80 and IVF 1:4</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18545]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>st </sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup> </sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>USG:</span></p>
<figure class="mm-figure" data-mm-figure-id="05fb1400bb8a42b59edba2cf" data-mm-topic-id="t-mm-09-022"><svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Source figure 05fb1400bb8a42b59edba2cf" viewbox="0 0 161925 104775" preserveaspectratio="xMidYMid meet" data-mm-object-manifest="c3a50d4d586920614bdf1030b16eaba1aa849c71432d062536b46fcadaf39568"><defs><clippath id="clip-c7023e9a48657300c4e1" clippathunits="userSpaceOnUse"><path d="M 0 0 L 159385 0 L 159385 104140 L 0 104140 Z"></path></clippath></defs><g data-mm-object-id="c7023e9a48657300c4e1" transform="translate(0 0)"><g transform="translate(0 0)" clip-path="url(#clip-c7023e9a48657300c4e1)"><image href="/uploads/content-images/maternal-mind-book/f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605/media/12a77440f398da19557b965eed8960de2ae9de21bfbd5eb346e550b8a1c543ae.png" x="0" y="0" width="159385" height="104140" preserveaspectratio="none"></image></g></g></svg></figure>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18546]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>11 – 13 + 6weeks.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18547]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>G. Age by CRL – twins </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>/</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>triplets (larger baby’s CRL</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> is used for determination of gestational age</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>).</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18548]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>No of Fetuses.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[18549]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>No of placenta.</span></span></div>
