INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-book-t-mm-10-006-0', 't-mm-10-006', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-10-006" hidden></div>
