INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-book-t-mm-10-019-0', 't-mm-10-019', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-10-019" hidden></div>
<div class="mm-heading mm-h3 mm-header-banner mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20902]" style="background-color: #9CC2E5; color: #FFFFFF; padding: 6px 12px; border-radius: 4px; font-weight: 700; margin-top: 8pt; margin-bottom: 4pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">8.</span><span class="mm-list-body"><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>WOMAN WITH OBSTETRIC COMPLICATIONS OR NO ANTENATAL CARE</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20903]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">54.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>More anxious </span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20904]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">55.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Need information regarding birth plan, risks and benefits of options of care</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20905]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">56.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Involve them in decision making</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20906]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">57.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Provide information about care in labor and mode of birth according to </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>personalized</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> circumstances and local/ national guidance.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20907]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Recognize following risk/ Concerns:</strong></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20908]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Pyrexia</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20909]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Sepsis</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20910]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Breach presentation</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20911]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Suspected SGA</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20912]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Suspected LGA</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20913]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Previous C/S</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20914]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>No ANC</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20915]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">58.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>If any of above is observed, escalate the care as needed.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20916]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">59.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Observe following parameters</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20917]" style="margin-bottom: 8pt; margin-left: 72pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1 hourly – pulse</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20918]" style="margin-bottom: 8pt; margin-left: 72pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>4 hourly – B.P, Temperature</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20919]" style="margin-bottom: 8pt; margin-left: 72pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Record urine output.</span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20920]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">60.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Adjust observations when needed.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20921]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Observations of women with.</strong></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20922]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">61.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Temp &gt; 38</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>0</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>C one reading.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20923]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">62.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Temp &gt; 37.5</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>0</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>C on two readings 1 hour apart</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20924]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">63.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Sepsis or suspected sepsis</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20925]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">64.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>APH</span></span></div>
<figure class="mm-figure" data-mm-figure-id="c6d267d309c67d85e4790320" data-mm-topic-id="t-mm-10-019"><svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Source figure c6d267d309c67d85e4790320" viewbox="1666875 142875 295275 447675" preserveaspectratio="xMidYMid meet" data-mm-object-manifest="94bf3e9c5476fda7a884c10955557b0a8dcd0cc2b30b1c3a3c97195f330715f9"><g data-mm-object-id="4aed554be1ca0acc023d" transform="translate(1701478 155728)"><g transform="translate(0 0)"><path d="M 0 274898 L 53533 274898 L 53533 0 L 160599 0 L 160599 274898 L 214132 274898 L 107066 381964 Z" fill="#FFFFFF" fill-opacity="1" stroke="#4472C4" stroke-opacity="1" stroke-width="12700"></path></g></g></svg></figure>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20926]" style="margin-bottom: 8pt; margin-left: 36pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20927]" style="text-align: center; margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Follow the table</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20928]" style="margin-bottom: 8pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20929]" style="text-align: center; margin-bottom: 8pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20930]" style="margin-bottom: 8pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[20931]" style="margin-bottom: 10pt"><span class="mm-run" style=''color: #44546A; font-family: "Calibri", sans-serif; font-size: 11pt''><em>Table </em></span><span class="mm-run" style=''color: #44546A; font-family: "Calibri", sans-serif; font-size: 11pt''><em>50</em></span><span class="mm-run" style=''color: #44546A; font-family: "Calibri", sans-serif; font-size: 11pt''><em>. Routine maternal observations for women in labour with fever, suspected sepsis, sepsis or intrapartum haemorrhage:</em></span></p>
<div class="mm-table-scroll" role="region" tabindex="0"><table class="mm-table" style="border-collapse:collapse;table-layout:fixed;margin-left:5.3pt;border-top:0.75pt solid #000000;border-right:0.75pt solid #000000;border-bottom:0.75pt solid #000000;border-left:0.75pt solid #000000;"><colgroup><col style="width:100.65pt;"><col style="width:82.55pt;"><col style="width:106.2pt;"><col style="width:91.25pt;"><col style="width:138.15pt;"></colgroup><tbody><tr data-mm-row-height-twips="648" data-mm-row-height-rule="auto"><td style="white-space:pre-wrap;width:100.65pt;background-color:#B4C6E7;border-top:0.75pt solid #000000;border-right:0.75pt solid #000000;border-bottom:0.75pt solid #000000;border-left:0.75pt solid #000000;padding-right:0pt;padding-left:0pt;"><p style="margin:0;text-align:center;padding-left:0.35pt;padding-right:38.5pt;margin-top:5.05pt;margin-bottom:0pt;"><span class="mm-run" style=''color:#282828;font-family:"Tahoma", sans-serif;font-size:12pt''><strong>Maternal observations</strong></span></p></td><td style="white-space:pre-wrap;width:82.55pt;background-color:#B4C6E7;border-top:0.75pt solid #000000;border-right:0.75pt solid #000000;border-bottom:0.75pt solid #000000;border-left:0.75pt solid #000000;padding-right:0pt;padding-left:0pt;"><p style="margin:0;text-align:center;padding-left:0.35pt;margin-top:10.45pt;margin-bottom:0pt;"><span class="mm-run" style=''color:#282828;font-family:"Tahoma", sans-serif;font-size:12pt''><strong>Fever</strong></span></p></td><td style="white-space:pre-wrap;width:106.2pt;background-color:#B4C6E7;border-top:0.75pt solid #000000;border-right:0.75pt solid #000000;border-bottom:0.75pt solid #000000;border-left:0.75pt solid #000000;padding-right:0pt;padding-left:0pt;"><p style="margin:0;text-align:center;padding-left:0.4pt;margin-bottom:0pt;"><span class="mm-run" style=''color:#282828;font-family:"Tahoma", sans-serif;font-size:12pt''><strong>Suspected sepsis – </strong></span><span class="mm-run" style=''color:#282828;font-family:"Tahoma", sans-serif;font-size:12pt''><strong>concern</strong></span><span class="mm-run" style=''color:#282828;font-family:"Tahoma", sans-serif;font-size:12pt''><strong> </strong></span><span class="mm-run" style=''color:#282828;font-family:"Tahoma", sans-serif;font-size:12pt''><strong>insufficient</strong></span><span class="mm-run" style=''color:#282828;font-family:"Tahoma", sans-serif;font-size:12pt''><strong> </strong></span><span class="mm-run" style=''color:#282828;font-family:"Tahoma", sans-serif;font-size:12pt''><strong>for </strong></span><span class="mm-run" style=''color:#282828;font-family:"Tahoma", sans-serif;font-size:12pt''><strong>antibiotic</strong></span><span class="mm-run" style=''color:#282828;font-family:"Tahoma", sans-serif;font-size:12pt''><strong> </strong></span><span class="mm-run" style=''color:#282828;font-family:"Tahoma", sans-serif;font-size:12pt''><strong>treatment</strong></span></p></td><td style="white-space:pre-wrap;width:91.25pt;background-color:#B4C6E7;border-top:0.75pt solid #000000;border-right:0.75pt solid #000000;border-bottom:0.75pt solid #000000;border-left:0.75pt solid #000000;padding-right:0pt;padding-left:0pt;"><p style="margin:0;text-align:center;padding-left:0.4pt;padding-right:1.5pt;margin-bottom:0pt;"><span class="mm-run" style=''color:#282828;font-family:"Tahoma", sans-serif;font-size:12pt''><strong>Sepsis</strong></span><span class="mm-run" style=''color:#282828;font-family:"Tahoma", sans-serif;font-size:12pt''><strong> </strong></span><span class="mm-run" style=''color:#282828;font-family:"Tahoma", sans-serif;font-size:12pt''><strong>or</strong></span><span class="mm-run" style=''color:#282828;font-family:"Tahoma", sans-serif;font-size:12pt''><strong> </strong></span><span class="mm-run" style=''color:#282828;font-family:"Tahoma", sans-serif;font-size:12pt''><strong>suspected sepsis – on </strong></span><span class="mm-run" style=''color:#282828;font-family:"Tahoma", sans-serif;font-size:12pt''><strong>antibiotic</strong></span><span class="mm-run" style=''color:#282828;font-family:"Tahoma", sans-serif;font-size:12pt''><strong> </strong></span><span class="mm-run" style=''color:#282828;font-family:"Tahoma", sans-serif;font-size:12pt''><strong>treatment</strong></span></p></td><td style="white-space:pre-wrap;width:138.15pt;background-color:#B4C6E7;border-top:0.75pt solid #000000;border-right:0.75pt solid #000000;border-bottom:0.75pt solid #000000;border-left:0.75pt solid #000000;padding-right:0pt;padding-left:0pt;"><p style="margin:0;text-align:center;padding-left:0.4pt;margin-top:10.45pt;margin-bottom:0pt;"><span class="mm-run" style=''color:#282828;font-family:"Tahoma", sans-serif;font-size:12pt''><strong>Intrapartum</strong></span><span class="mm-run" style=''color:#282828;font-family:"Tahoma", sans-serif;font-size:12pt''><strong> </strong></span><span class="mm-run" style=''color:#282828;font-family:"Tahoma", sans-serif;font-size:12pt''><strong>haemorrhage</strong></span></p></td></tr><tr data-mm-row-height-twips="648" data-mm-row-height-rule="auto"><td style="white-space:pre-wrap;width:100.65pt;border-top:0.75pt solid #000000;border-right:0.75pt solid #000000;border-bottom:0.75pt solid #000000;border-left:0.75pt solid #000000;padding-right:0pt;padding-left:0pt;"><p style="margin:0;margin-top:8.6pt;margin-bottom:0pt;"></p><p style="margin:0;padding-left:4.1pt;margin-bottom:0pt;"><span class="mm-run" style=''color:#282828;font-family:"Tahoma", sans-serif;font-size:12pt''>Pulse</span></p></td><td style="white-space:pre-wrap;width:82.55pt;border-top:0.75pt solid #000000;border-right:0.75pt solid #000000;border-bottom:0.75pt solid #000000;border-left:0.75pt solid #000000;padding-right:0pt;padding-left:0pt;"><p style="margin:0;margin-top:8.6pt;margin-bottom:0pt;"></p><p style="margin:0;padding-left:4.1pt;margin-bottom:0pt;"><span class="mm-run" style=''color:#282828;font-family:"Tahoma", sans-serif;font-size:12pt''>Hourly</span></p></td><td style="white-space:pre-wrap;w