INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-book-t-mm-10-035-0', 't-mm-10-035', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-10-035" hidden></div>
<h2 class="mm-heading mm-h2 mm-header-banner" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21887]" style="background-color: #2F5496; color: #FFFFFF; padding: 6px 12px; border-radius: 4px; font-weight: 700; margin-top: 8pt; margin-bottom: 4pt"><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>11. </strong></span><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>CORD PROLAPSE</strong></span></h2>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21888]" style="margin-bottom: 8pt; margin-left: 54pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>0.1 – 0.6%</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21889]" style="margin-bottom: 8pt; margin-left: 54pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1% in breech</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21890]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Perinatal mortality 91/1000</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21891]" style="text-align: center; margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Risk factors:</strong></u></span></p>
<figure class="mm-figure" data-mm-figure-id="9b7f9009e2510ac85dc92269" data-mm-topic-id="t-mm-10-035"><svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Source figure 9b7f9009e2510ac85dc92269" viewbox="3819525 152400 38100 257175" preserveaspectratio="xMidYMid meet" data-mm-object-manifest="35d2e2408161db016aa399bd344a627cd360dd8f684aff6c7da548b31bdb1f43"><g data-mm-object-id="a383dbf6919460f6422a" transform="translate(3830320 166370)"><g transform="translate(0 0)"><path d="M 0 0 L 1 193040" fill="none" fill-opacity="0" stroke="#4472C4" stroke-opacity="1" stroke-width="12700"></path></g></g></svg></figure>
<figure class="mm-figure" data-mm-figure-id="0cd9fc628178d2207c1d02dd" data-mm-topic-id="t-mm-10-035"><svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Procedure related:Half of cord prolapse (are procedure related)1.  ARM with high presenting part2.  Vaginal manipulation with ruptured membranes Avoid upward pushing3. ECV4. Stabilizing induction5. Insertion of I/U Catheter Esp if filled more than 180ml." viewbox="619125 9525 6496050 3248025" preserveaspectratio="xMidYMid meet" data-mm-object-manifest="2cdd11a117c00a19ce138dd667fd883f5772aefa8780d7831c6e1ef30b213b31"><defs><marker id="arrow-end-6b1e1b4404a33039b983" markerwidth="10" markerheight="7" refx="9" refy="3.5" orient="auto" markerunits="strokeWidth"><path d="M 0 0 L 10 3.5 L 0 7 Z" fill="#4472C4"></path></marker><marker id="arrow-end-7ad02f76d1597a700f64" markerwidth="10" markerheight="7" refx="9" refy="3.5" orient="auto" markerunits="strokeWidth"><path d="M 0 0 L 10 3.5 L 0 7 Z" fill="#4472C4"></path></marker></defs><g data-mm-object-id="2fabeafb6ef4eef94e50" transform="translate(4661477 250652)"><g transform="translate(0 0)"><path d="M 0 0 L 2445328 0 L 2445328 2999509 L 0 2999509 Z" fill="none" fill-opacity="0" stroke="none" stroke-opacity="0" stroke-width="6350"></path><g data-mm-text-anchor="t" transform="translate(0 45720)"><g transform="scale(12700)"><text data-mm-wrapped-line="0" x="7.2" y="12" text-anchor="start" xml:space="preserve"><tspan font-size="12" font-weight="700" font-style="italic">Procedure related:</tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="0" x="43.2" y="33.95" text-anchor="start" xml:space="preserve"><tspan font-size="12">Half of cord prolapse </tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="1" x="43.2" y="47.9" text-anchor="start" xml:space="preserve"><tspan font-size="12">(are procedure related)</tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="0" x="25.2" y="69.85" text-anchor="start" xml:space="preserve"><tspan font-size="12">1.  ARM with high presenting </tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="1" x="43.2" y="82.8" text-anchor="start" xml:space="preserve"><tspan font-size="12">part</tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="0" x="25.2" y="103.75" text-anchor="start" xml:space="preserve"><tspan font-size="12">2.  Vaginal manipulation with </tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="1" x="43.2" y="116.7" text-anchor="start" xml:space="preserve"><tspan font-size="12">ruptured membranes </tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="0" x="43.2" y="137.65" text-anchor="start" xml:space="preserve"><tspan font-size="12">Avoid upward pushing</tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="0" x="25.2" y="159.6" text-anchor="start" xml:space="preserve"><tspan font-size="12">3. ECV</tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="0" x="25.2" y="180.55" text-anchor="start" xml:space="preserve"><tspan font-size="12">4. Stabilizing induction</tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="0" x="25.2" y="201.5" text-anchor="start" xml:space="preserve"><tspan font-size="12">5. Insertion of I/U Catheter </tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="0" x="43.2" y="222.45" text-anchor="start" xml:space="preserve"><tspan font-size="12">Esp if filled more than </tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="1" x="43.2" y="236.4" text-anchor="start" xml:space="preserve"><tspan font-size="12">180ml.</tspan></text></g></g></g></g><g data-mm-object-id="553ce6934f0a6fd315cc" transform="translate(741680 56515)"><g transform="translate(0 0) translate(2225040 7620) rotate(0) scale(1 -1) translate(-2225040 -7620)"><path d="M 0 0 L 4450080 15240" fill="none" fill-opacity="0" stroke="#4472C4" stroke-opacity="1" stroke-width="12700"></path></g></g><g data-mm-object-id="6b1e1b4404a33039b983" transform="translate(741680 71755)"><g transform="translate(0 0)"><path d="M 0 0 L 5080 284480" fill="none" fill-opacity="0" stroke="#4472C4" stroke-opacity="1" stroke-width="12700" marker-end="url(#arrow-end-6b1e1b4404a33039b983)"></path></g></g><g data-mm-object-id="7ad02f76d1597a700f64" transform="translate(5191760 56515)"><g transform="translate(0 0)"><path d="M 0 0 L 5080 284480" fill="none" fill-opacity="0" stroke="#4472C4" stroke-opacity="1" stroke-width="12700" marker-end="url(#arrow-end-7ad02f76d1597a700f64)"></path></g></g></svg></figure>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21893]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><em><strong>General</strong></em></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21894]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Multiparty</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21895]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>2. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>LBW &lt; 2.5kg</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21896]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>3. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>PTL &lt; 37weeks</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21897]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>4. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Congenital anomalies</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21898]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>5. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Breech</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21899]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>6. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Transverse lie</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21900]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Unstable lie – lie changes repeatedly</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21901]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Oblique</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> lie after 37 weeks</span></p>
<figure class="mm-figure" data-mm-figure-id="2d9d7a446f3bf8538d9d1886" data-mm-topic-id="t-mm-10-035"><svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Source figure 2d9d7a446f3bf8538d9d1886" viewbox="1952625 -9525 200025 276225" preserveaspectratio="xMidYMid meet" data-mm-object-manifest="03471129bac0a8242b68b304599200a2fbadefc4e52dfc2a265817291f56bf4a"><g data-mm-object-id="276e62815148d1bc95e0" transform="translate(1986280 5080)"><g transform="translate(0 0)"><path d="M 0 147320 L 30480 147320 L 30480 0 L 91440 0 L 91440 147320 L 121920 147320 L 60960 208280 Z" fill="#FFFFFF" fill-opacity="1" stroke="#5B9BD5" stroke-opacity="1" stroke-width="12700"></path></g></g></svg></figure>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21903]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-tab" aria-hidden="true">	</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Admit + Stabilizing induction</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21904]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>7. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>2</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>nd</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> twin – treatment IPV + Breech extraction</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21905]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>8. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Polyhydramnios</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21906]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>9. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Un – engaged fetal head</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21907]" style="margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>10. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Low lying placenta</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21908]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Cord presentation:</strong></u></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21909]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>USG only in research setting</span></span></div>
