INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-book-t-mm-10-036-0', 't-mm-10-036', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-10-036" hidden></div>
<h2 class="mm-heading mm-h2 mm-header-banner" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21953]" style="background-color: #2F5496; color: #FFFFFF; padding: 6px 12px; border-radius: 4px; font-weight: 700; margin-top: 8pt; margin-bottom: 4pt"><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>12. </strong></span><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>ASSISTED VAGINAL BIRTH (AVB):</strong></span></h2>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21954]" style="margin-bottom: 8pt; margin-left: 54pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>- </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>10 – 15%</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21955]" style="margin-bottom: 8pt; margin-left: 54pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>- </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Nulliparous 1/3</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21956]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Indications:</strong></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21957]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">311.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Fetal:</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21958]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>CTG – Pathological</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21959]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>FBS – Abnormal</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21960]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>Thick meconium</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21961]" style="margin-bottom: 8pt; margin-left: 72pt"> </p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21962]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">312.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Maternal:</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21963]" style="margin-bottom: 8pt; margin-left: 54pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Lack of progress</span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21964]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>primi: (</span><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>a</span><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>). 3</span><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>hours</span><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>with epidural (</span><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>b</span><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>). 2 hours without epidural</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[21965]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>multi: (</span><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>a</span><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>). 2 hours with epidural (</span><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>b</span><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''>). 1 hour without epidural</span></span></div>
