INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-book-t-mm-10-036-2', 't-mm-10-036', 'document_html', '<figure class="mm-figure" data-mm-figure-id="ce9cd1bfcbf7749f63cd2b8f" data-mm-topic-id="t-mm-10-036"><svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Full abdominal and vaginalexaminationPreparation of motherPreparation of staffHead is ≤ 1/5 palpable per abdomen (in most cases not palpable) Cervix is fully dilated and the membranes rupturedStation at level of ischial spines or belowPosition of the fetal head has been determinedUSG assessment of fetal position is reliable and is recommended routinely not recommendedCaput and molding are no more than moderate (or +2) aPelvis is deemed adequateClear explanation given and informed consent taken and documented in women’s case notesTrust established and full cooperation sought and agreed with woman Appropriate analgesia is in place: for midpelvic or rotational birth, this will usually be a regional block; a pudendal block may be acceptable depending on urgency; and a perineal block may be sufficient for low or outlet birth Maternal bladder has been emptiedIndwelling catheter has been removed or balloon deflated Aseptic techniqueOperator has the knowledge, experience and skill necessaryAdequate facilities are available (equipment, bed, lighting) and access to an operating theatreBackup plan: for midpelvic births, theatre facilities should be available to allow a caesarean birth to be performed without delay; a senior obstetrician should be present if an inexperienced obstetrician is conducting the birthAnticipation of complications that may arise (e.g. shoulder dystocia, perineal trauma, postpartum haemorrhage)Personnel present who are trained in neonatal resuscitation" viewbox="457200 352425 6581775 5229225" preserveaspectratio="xMidYMid meet" data-mm-object-manifest="eb0f49cd70f92c445d40fc8cc574625daac44100d72699104a00102d0f95cc53"><g data-mm-object-id="c8e4ab44e37edd62a44e" transform="translate(459105 356870) translate(3285490 2607945) rotate(0) scale(1 1) translate(-3285490 -2607945) scale(1.12852653 1.7252678) translate(-97917 -32242)"><g transform="translate(97917 74640)"><path d="M 0 0 L 1271270 0 L 1271270 1296045 L 0 1296045 Z" fill="#FFFFFF" fill-opacity="1" stroke="#FFFFFF" stroke-opacity="1" stroke-width="12700"></path><g data-mm-text-anchor="t" transform="translate(0 0)"><g transform="scale(12700)"><text data-mm-wrapped-line="0" x="0" y="12" text-anchor="start" xml:space="preserve"><tspan font-size="12">Full abdominal and </tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="1" x="0" y="24" text-anchor="start" xml:space="preserve"><tspan font-size="12">vaginal</tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="0" x="0" y="44.95" text-anchor="start" xml:space="preserve"><tspan font-size="12">examination</tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="0" x="0" y="66.9" text-anchor="start" xml:space="preserve"></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="0" x="0" y="95.35" text-anchor="start" xml:space="preserve"></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="0" x="0" y="115.8" text-anchor="start" xml:space="preserve"></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="0" x="0" y="129.75" text-anchor="start" xml:space="preserve"></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="0" x="0" y="141.75" text-anchor="start" xml:space="preserve"></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="0" x="0" y="153.75" text-anchor="start" xml:space="preserve"><tspan font-size="12">Preparation of </tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="1" x="0" y="165.75" text-anchor="start" xml:space="preserve"><tspan font-size="12">mother</tspan></text></g></g></g><g transform="translate(194344 2039076)"><path d="M 0 0 L 1029843 0 L 1029843 193739 L 0 193739 Z" fill="#FFFFFF" fill-opacity="1" stroke="#FFFFFF" stroke-opacity="1" stroke-width="12700"></path><g data-mm-text-anchor="t" transform="translate(0 0)"><g transform="scale(12700)"><text data-mm-wrapped-line="0" x="0" y="12" text-anchor="start" xml:space="preserve"><tspan font-size="12">Preparation </tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="1" x="0" y="24" text-anchor="start" xml:space="preserve"><tspan font-size="12">of staff</tspan></text></g></g></g><g transform="translate(1607821 32242)"><path d="M 0 0 L 4312715 0 L 4312715 3023235 L 0 3023235 Z" fill="#FFFFFF" fill-opacity="1" stroke="#FFFFFF" stroke-opacity="1" stroke-width="12700"></path><g data-mm-text-anchor="t" transform="translate(0 0)"><g transform="scale(12700)"><text data-mm-wrapped-line="0" x="18" y="13.6" text-anchor="start" xml:space="preserve"><tspan font-size="12">Head is ≤ 1/5 palpable per abdomen (in most cases </tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="1" x="36" y="25.6" text-anchor="start" xml:space="preserve"><tspan font-size="12">not palpable) </tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="0" x="18" y="47.2" text-anchor="start" xml:space="preserve"><tspan font-size="12">Cervix is fully dilated and the membranes ruptured</tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="0" x="18" y="67.2" text-anchor="start" xml:space="preserve"><tspan font-size="12">Station at level of ischial spines </tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="1" x="36" y="79.2" text-anchor="start" xml:space="preserve"><tspan font-size="12">or below</tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="0" x="18" y="99.2" text-anchor="start" xml:space="preserve"><tspan font-size="12">Position of the fetal head has </tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="1" x="36" y="111.2" text-anchor="start" xml:space="preserve"><tspan font-size="12">been determined</tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="0" x="18" y="131.2" text-anchor="start" xml:space="preserve"><tspan font-size="12">USG assessment of fetal position </tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="1" x="36" y="143.2" text-anchor="start" xml:space="preserve"><tspan font-size="12">is reliable and is recommended </tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="2" x="36" y="155.2" text-anchor="start" xml:space="preserve"><tspan font-size="12">routinely not recommended</tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="0" x="18" y="175.2" text-anchor="start" xml:space="preserve"><tspan font-size="12">Caput and molding are no more than moderate (or </tspan><tspan font-size="12">+</tspan><tspan font-size="12">2)</tspan><tspan font-size="12" baseline-shift="super"> a</tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="0" x="18" y="195.2" text-anchor="start" xml:space="preserve"><tspan font-size="12">Pelvis is deemed adequate</tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="0" x="0" y="215.2" text-anchor="start" xml:space="preserve"></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="0" x="18" y="240.5" text-anchor="start" xml:space="preserve"><tspan font-size="12">Clear explanation given and informed consent taken and </tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="1" x="36" y="252.5" text-anchor="start" xml:space="preserve"><tspan font-size="12">documented in women’s case notes</tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="0" x="18" y="272.5" text-anchor="start" xml:space="preserve"><tspan font-size="12">Trust established and full cooperation sought and agreed </tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="1" x="36" y="284.5" text-anchor="start" xml:space="preserve"><tspan font-size="12">with woman </tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="0" x="18" y="304.5" text-anchor="start" xml:space="preserve"><tspan font-size="12">Appropriate analgesia is in place: for midpelvic or </tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="1" x="36" y="316.5" text-anchor="start" xml:space="preserve"><tspan font-size="12">rotational birth, this will usually be a regional block; a </tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="2" x="36" y="328.5" text-anchor="start" xml:space="preserve"><tspan font-size="12">pudendal block may be acceptable depending on urgency; </tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="3" x="36" y="340.5" text-anchor="start" xml:space="preserve"><tspan font-size="12">and a perineal block may be sufficient for low or outlet </tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="4" x="36" y="352.5" text-anchor="start" xml:space="preserve"><tspan font-size="12">birth </tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="0" x="18" y="372.5" text-anchor="start" xml:space="preserve"><tspan font-size="12">Maternal bladder has been emptied</tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="0" x="18" y="392.5" text-anchor="start" xml:space="preserve"><tspan font-size="12">Indwelling catheter has been removed or balloon </tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="1" x="36" y="404.5" text-anchor="start" xml:space="preserve"><tspan font-size="12">deflated </tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="0" x="18" y="424.5" text-anchor="start" xml:space="preserve"><tspan font-size="12">Aseptic technique</tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="0" x="0" y="444.5" text-anchor="start" xml:space="preserve"></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="0" x="18" y="467.55" text-anchor="start" xml:space="preserve"><tspan font-size="12">Operator has the knowledge, experience and skill </tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="1" x="36" y="479.55" text-anchor="start" xml:space="preserve"><tspan font-size="12">necessary</tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="0" x="18" y="500.75" text-anchor="start" xml:space="preserve"><tspan font-size="12">Adequate facilities are available (equipment, bed, lighting) </tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="1" x="36" y="512.75" text-anchor="start" xml:space="preserve"><tspan font-size="12">and access to an operating theatre</tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="0" x="18" y="532.75" text-anchor="start" xml:space="preserve"><tspan font-size="12">Backup plan: for midpelvic births, theatre facilities </tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="1" x="36" y="544.75" text-anchor="start" xml:space="preserve"><tspan font-size="12">should be available to allow a caesarean birth to be </tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="2" x="36" y="556.75" text-anchor="start" xml:space="preserve"><tspan font-size="12">performed without delay; a senior obstetrician should </tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="3" x="36" y="568.75" text-anchor="start" xml:space="preserve"><tspan font-size="12">be present if an inexperienced obstetrician is </tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="4" x="36" y="580.75" text-anchor="start" xml:space="preserve"><tspan font-size="12">conducting the birth</tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="0" x="18" y="601.05" text-anchor="start" xml:space="preserve"><tspan font-size="12">Anticipation of complications that may arise (e.g. shoulder </tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="1" x="36" y="613.05" text-anchor="start" xml:space="preserve"><tspan font-size="12">dystocia, perineal trauma, postpartum haemorrhage)</tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="0" x="18" y="633.05" text-anchor="start" xml:space="preserve"><tspan font-size="12">Personnel present who are trained in neonatal </tspan></text></g><g transform="scale(12700)"><text data-mm-wrapped-line="1" x="36" y="645.05" text-anchor="start" xml:space="preserve"><tspan font-size="12">resuscitation</tspan></text></g></g></g></g></svg></figure>
