INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-book-t-mm-10-039-0', 't-mm-10-039', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-10-039" hidden></div>
<div class="mm-heading mm-h2 mm-header-banner mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22431]" style="background-color: #2F5496; color: #FFFFFF; padding: 6px 12px; border-radius: 4px; font-weight: 700; margin-top: 8pt; margin-bottom: 4pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">15.</span><span class="mm-list-body"><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 16pt''><strong>PERIMORTEM C/S</strong></span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22432]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">391.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Cardiac arrest 1/12500 pregnancy</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22433]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">392.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Commonest cause </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>haemorrhage</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 45%, </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>AF embolism</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 13</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>%,</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>An</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>a</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>esthesia 3%, Trauma 3%</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22434]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">393.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Alternative name resuscitative hysterotomy </span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22435]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">394.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Infant survival after PMCS = 69% Maternal </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>survival</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 54%</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>,</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 78</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>% survive</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>with mod</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>erate </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>impaired neurological functions.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22436]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">395.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Aortocaval compression</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> by uterus reduces venous return </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>by </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>60%</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22437]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Initial Resuscitation:</strong></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22438]" style="padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Airway</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>: by </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>small tube to avoid failed intubation</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22439]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Breathing</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>:</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> High flow O</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sub>2</sub></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sub>,</sub></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 10 – 15l/min – detrimental to fetus but required for mother.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22440]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Circulation</strong></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>: CPR</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>30:2, i/v line, fluids</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22441]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Compression @ rate of 100/min with 2 rescue breaths after intubation v</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>entilation</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> @ rate of 100/min</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22442]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>In h</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>eavier Breast</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> apply</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>defibrillator</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> pads</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> ant</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>erior</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> &amp; pos</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>terior </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>pericardium</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22443]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Uterus displacement up off and over</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22444]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Cannula 16g I/V</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> in</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>upper</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> body </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>if failed use</span><span class="mm-tab" aria-hidden="true">	</span><span class="mm-run" style=''color: #2F5496; font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>intraosseous</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> a</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>cc</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ess.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22445]" style="margin-bottom: 8pt; margin-left: 18pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>PMCS</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> =&gt;</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>indicated if gestational age </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>is &gt;</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> 20weeks after 4min of ineffective resuscitation.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22446]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>-Performed in </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Labo</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>u</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>r room/ ER</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22447]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>-</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Without anesthesia</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22448]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>-</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Equipment</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> needed</span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22449]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Curved 10n</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>0</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> blade over </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>scalpel</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22450]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>2/3 ligature/ clamps.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22451]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u>Abdominal Incision</u></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22452]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">396.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Preferabl</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>y</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> midline</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22453]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Easy approach</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22454]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Rapid entry</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22455]" style="margin-bottom: 8pt; padding-left: 72pt"><span class="mm-list-marker" aria-hidden="true">-</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Exploration of abdominal </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>viscera</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> is done if suspected visual injury</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22456]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">397.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Transverse – if clinician is not well trained or familiar with midline incision.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22457]" style="margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u>Uterine incision</u></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22458]" style="padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">398.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>20 – 28 weeks – vertical incision avoiding bladder</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22459]" style="padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">399.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>&gt; 28 weeks – Transverse incision</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22460]" style="padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">400.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Vertical incision more rapid with more chances of bladder injury.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22461]" style="margin-left: 18pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>      </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u>Placenta:</u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22462]" style="margin-left: 72pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Deliver or leave in situ</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22463]" style="margin-left: 72pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Pack the incised uterus and cover abdomen</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22464]"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Management after resuscitation is complete/ Successful:</strong></u></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22465]" style="padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">401.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Shift to OT</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22466]" style="padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">402.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>General Anesthesia</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22467]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">403.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Closure of uterus</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>;</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22468]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Vertical incision by 3 layered closure</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22469]" style="margin-bottom: 8pt; margin-left: 72pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>- 1</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>st</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>layer; –</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>figure of 8</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> by </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>2 </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>stitches.</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22470]" style="margin-bottom: 8pt; margin-left: 72pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>- </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>2</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>nd</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> and 3</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><sup>rd</sup></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> interrupted </span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22471]" style="margin-bottom: 8pt; margin-left: 72pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>-</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>suture </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>type;</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>n</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>umber 1 </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>polyglactin</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22472]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>            </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Transverse</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> incision; close</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> as per routine</span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22473]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">404.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Secure hemostasis and close abdomen</span></span></div>
<figure class="mm-figure" data-mm-figure-id="44c09bcee3900a961b4228c7" data-mm-topic-id="t-mm-10-039"><svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Source figure 44c09bcee3900a961b4228c7" viewbox="619125 9525 85725 590550" preserveaspectratio="xMidYMid meet" data-mm-object-manifest="4856506e4563870feb2dc8cb3f29b0c38207e55a86cd56956ab3c86404346e7e"><g data-mm-object-id="3e3d9efc5cdf84468f21" transform="translate(632574 16743)"><g transform="translate(0 0)"><path d="M 45719 543208 A 45719 3809.76427 0 0 1 0 539398.23573 L 0 3809.76427 A 45719 3809.76427 0 0 1 45719 0 Z" fill="none" fill-opacity="0" stroke="#000000" stroke-opacity="1" stroke-width="12700"></path><path d="M 45719 543208 A 45719 3809.76427 0 0 1 0 539398.23573 L 0 3809.76427 A 45719 3809.76427 0 0 1 45719 0" fill="none" fill-opacity="0" stroke="#000000" stroke-opacity="1" stroke-width="12700"></path></g></g></svg></figure>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22474]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">405.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Placement of non-suction drain.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22475]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">406.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Pack the abd</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>omen</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong> &amp; </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>close with</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong> few </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>sutures</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong> and remove pack after 24 hours in OT.</strong></u></span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22476]" style="margin-bottom: 8pt; margin-left: 36pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22477]" style="margin-bottom: 8pt; margin-left: 18pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Management when Resuscitation is unsuccessful</strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>:</span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22478]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">407.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Stop resuscitation – decision is made by attending senior consultant team (obs</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>tetrician,</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> An</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>a</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>esthetist, ER staff)</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22479]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Agreement of all staff is must.</span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22480]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">408.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Inform coroner</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22481]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">409.</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Leave devices inside if postmortem is required</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22482]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Recommendations for post mortem:</strong></u></span></p>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22483]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>All devices like catheter, tube, I/V line should be in</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>situ @ the time of disclosure of death to attendants</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22484]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Leave placenta in</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>situ, uterus un</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>sutured, abd</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>omen</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> open</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22485]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> pack and</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> do the</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> dress</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>ing of</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''> the abd</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>omen</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>.</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22486]" style="margin-bottom: 8pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">⇨</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Clear documentation of all events of PMCS in notes.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22487]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Neonatal care</strong></u></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[22488]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><u><strong>Debriefing </strong></u></span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>of relative and staff.</span></p>
