INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-book-t-mm-11-014-0', 't-mm-11-014', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-11-014" hidden></div>
<h3 class="mm-heading mm-h3 mm-header-banner" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23713]" style="background-color: #9CC2E5; color: #FFFFFF; padding: 6px 12px; border-radius: 4px; font-weight: 700; margin-top: 8pt; margin-bottom: 4pt"><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>6.8. </span><span class="mm-run" style=''color: #FFFFFF; font-family: "Calibri Light", sans-serif; font-size: 14pt''>EATING DISORDERS:</span></h3>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23714]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>6 – fold     in perinatal mortality</span></span></div>
<figure class="mm-figure" data-mm-figure-id="70717ba04641777b5897ca29" data-mm-topic-id="t-mm-11-014"><svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Source figure 70717ba04641777b5897ca29" viewbox="1143000 -85725 247650 304800" preserveaspectratio="xMidYMid meet" data-mm-object-manifest="c087dc64ce07a28035ad148accca71861fc6a51562fa6fe6cf032591cfa8803c"><defs><marker id="arrow-end-643d3baceae259e7f741" markerwidth="10" markerheight="7" refx="9" refy="3.5" orient="auto" markerunits="strokeWidth"><path d="M 0 0 L 10 3.5 L 0 7 Z" fill="#000000"></path></marker></defs><g data-mm-object-id="643d3baceae259e7f741" transform="translate(1266190 1270)"><g transform="translate(0 0) translate(2893.5 75235.5) rotate(0) scale(-1 -1) translate(-2893.5 -75235.5)"><path d="M 0 0 L 5787 150471" fill="none" fill-opacity="0" stroke="#000000" stroke-opacity="1" stroke-width="12700" marker-end="url(#arrow-end-643d3baceae259e7f741)"></path></g></g></svg></figure>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23715]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Association with psychiatric disorder</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23716]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Relapses in pregnancy</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23717]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Fetal growth abnormalities</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23718]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Feeding problems </span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23719]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>anorexia has highest mortality among all psychiatric disorders.</span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23720]" style="margin-bottom: 8pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''><strong>Management:</strong></span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23721]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>1. </span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Discuss healthy eating and its benefits</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23722]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>2.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Offer support regarding nutrition</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23723]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>3.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Psychological intervention</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[23724]" style="margin-bottom: 8pt; margin-left: 36pt"><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>4.</span><span class="mm-run" style=''font-family: "Calibri", sans-serif; font-size: 12pt''>Growth scans</span></p>', 0);

