INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-book-t-mm-12-005-0', 't-mm-12-005', 'document_html', '<div class="mm-release-marker" data-mm-release="f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605" data-mm-topic="t-mm-12-005" hidden></div>
<div class="mm-heading mm-h2 mm-header-banner mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24166]" style="background-color: #2F5496; color: #FFFFFF; padding: 6px 12px; border-radius: 4px; font-weight: 700; margin-top: 8pt; margin-bottom: 4pt; padding-left: 36pt"><span class="mm-list-marker" aria-hidden="true">6.</span><span class="mm-list-body"><span class="mm-run" style=''color: #FFFFFF; font-family: "Times New Roman", sans-serif; font-size: 16pt''><strong>REFLECTION</strong></span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24167]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''>Learning from own experience</span></span></div>
<div class="mm-para mm-list-item" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24168]" style="margin-bottom: 8pt; padding-left: 18pt"><span class="mm-list-marker" aria-hidden="true">•</span><span class="mm-list-body"><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''><u><strong>Kolb’s</strong></u></span><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''><u><strong> reflective practice</strong></u></span></span></div>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24169]" style="margin-bottom: 8pt; margin-left: 18pt"><span class="mm-run" style=''font-family: "Times New Roman", sans-serif; font-size: 12pt''>is a four-stage, continuous, experiential learning model where knowledge is created through transforming experience</span></p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24170]" style="margin-bottom: 8pt"> </p>
<figure class="mm-figure" data-mm-figure-id="12aebff154ab193979d7e917" data-mm-topic-id="t-mm-12-005"><svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Source figure 12aebff154ab193979d7e917" viewbox="0 0 3209925 3171825" preserveaspectratio="xMidYMid meet" data-mm-object-manifest="a3db9d7c4a9edcffc95f682d2a60acad9a65962e1ec18cabd3f2afd3b5f65e2a"><defs><clippath id="clip-a32a97be8eaebff59089" clippathunits="userSpaceOnUse"><path d="M 0 0 L 3204210 0 L 3204210 3171190 L 0 3171190 Z"></path></clippath></defs><g data-mm-object-id="a32a97be8eaebff59089" transform="translate(0 0)"><g transform="translate(0 0)" clip-path="url(#clip-a32a97be8eaebff59089)"><image href="/uploads/content-images/maternal-mind-book/f94027611ab71565c9dfd689046bb4a24db921b97ef1453416d5acfa140ed605/media/644e277fe44ac9733179e65bfbca1b3c961782bb8e749a0ab5b835ce52a6da43.png" x="0" y="0" width="3204210" height="3171190" preserveaspectratio="none"></image></g></g></svg></figure>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24172]" style="margin-bottom: 8pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24173]" style="margin-bottom: 8pt"> </p>
<p class="mm-para" data-mm-source-path="word/document.xml/w:document[1]/w:body[1]/w:p[24174]" style="margin-bottom: 8pt"> </p>
